public class NarrativeManager : MonoBehaviour
{
    private Story _story;
    private List<string> _currentChoices;

    void Start()
    {
        _story = new Story(inkJSONAsset.text);
        RefreshView();
    }

    void RefreshView()
    {
        while (_story.canContinue)
        {
            string text = _story.Continue();
            DisplayDialogue(text);
        }

        if (_story.currentChoices.Count > 0)
        {
            _currentChoices = _story.currentChoices
                .Select(c => c.text)
                .ToList();
            DisplayChoices(_currentChoices);
        }
        else
        {
            EndDialogue();
        }
    }

    public void MakeChoice(int choiceIndex)
    {
        _story.ChooseChoiceIndex(choiceIndex);
        RefreshView();
    }
}

public class CharacterController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private Animator animator;
    private NavMeshAgent _agent;
    private Vector2 _movement;

    void Start()
    {
        _agent = GetComponent<NavMeshAgent>();
        _agent.updateRotation = false;
        _agent.updateUpAxis = false;
    }

    void Update()
    {
        _movement.x = Input.GetAxisRaw("Horizontal");
        _movement.y = Input.GetAxisRaw("Vertical");

        animator.SetFloat("Horizontal", _movement.x);
        animator.SetFloat("Vertical", _movement.y);
        animator.SetFloat("Speed", _movement.sqrMagnitude);
    }

    void FixedUpdate()
    {
        Vector3 moveDirection = new Vector3(_movement.x, _movement.y, 0);
        _agent.velocity = moveDirection * moveSpeed;
    }
}

