public class AssetBundleManager : MonoBehaviour
{
    private Dictionary<string, AssetBundle> _loadedBundles = 
        new Dictionary<string, AssetBundle>();

    public async Task<T> LoadAssetAsync<T>(string bundleName, string assetName) 
        where T : UnityEngine.Object
    {
        if (!_loadedBundles.ContainsKey(bundleName))
        {
            string path = Path.Combine(
                Application.streamingAssetsPath, 
                bundleName
            );
            var bundleRequest = AssetBundle.LoadFromFileAsync(path);
            await bundleRequest;
            _loadedBundles[bundleName] = bundleRequest.assetBundle;
        }

        var bundle = _loadedBundles[bundleName];
        var assetRequest = bundle.LoadAssetAsync<T>(assetName);
        await assetRequest;
        return assetRequest.asset as T;
    }
}

