public class BuildScript
{
    [MenuItem("Build/Build All Platforms")]
    public static void BuildAllPlatforms()
    {
        BuildPlatform(BuildTarget.StandaloneWindows64, "Builds/Windows");
        BuildPlatform(BuildTarget.StandaloneOSX, "Builds/Mac");
        BuildPlatform(BuildTarget.StandaloneLinux64, "Builds/Linux");
    }

    private static void BuildPlatform(BuildTarget target, string path)
    {
        BuildPlayerOptions buildPlayerOptions = new BuildPlayerOptions
        {
            scenes = GetScenePaths(),
            locationPathName = path,
            target = target,
            options = BuildOptions.None
        };

        BuildPipeline.BuildPlayer(buildPlayerOptions);
    }

    private static string[] GetScenePaths()
    {
        return EditorBuildSettings.scenes
            .Where(s => s.enabled)
            .Select(s => s.path)
            .ToArray();
    }
}
